const ALL = [...PLAN, ...PLAN2, ...PLAN3, ...PLAN4, ...PLAN5];

function q(s) {
  return JSON.stringify(s);
}

function buildArticle(item) {
  const [a, b, c, d] = item.angles;
  const linkHints = item.links.map((l) => l.href).join(", ");
  const intro = `${item.title.replace(/:.*$/, "").trim()} — тема, с которой к нам часто приходят за ясностью. В Zovus можно получить спокойный разбор без давления «угадать будущее»: вы формулируете вопрос, выбираете инструмент и продолжаете диалог с наставником. Ниже — практичная рамка, чтобы сразу понять, с чего начать и куда перейти дальше (${linkHints}).`;
  const sections = [
    { heading: a.charAt(0).toUpperCase() + a.slice(1), body: `Разберём «${a}» применительно к теме «${item.title}». Важно отделить факт запроса от тревоги вокруг него: карты, числа или натал показывают динамику и варианты, а не приговор. Сформулируйте один ясный вопрос — так ответ в сервисе будет собраннее.` },
    { heading: b.charAt(0).toUpperCase() + b.slice(1), body: `Блок про «${b}» помогает увидеть структуру ситуации. В Zovus удобно опереться на готовый сценарий или расчёт, а затем уточнить детали в чате. Если ответ звучит жёстко — проверьте, не читаете ли вы его через страх; иногда достаточно сменить формулировку вопроса.` },
    { heading: c.charAt(0).toUpperCase() + c.slice(1), body: `Тема «${c}» часто становится мостом к действию. Запишите 1–2 наблюдения после разбора и выберите маленький шаг на ближайшие дни. Это превращает сеанс из «просто интересно» в опору для решения.` },
    { heading: d.charAt(0).toUpperCase() + d.slice(1), body: `Про «${d}»: если базового ответа мало, углубитесь через связанные разделы сайта или полный сеанс с наставником. Не сто́ит задавать тот же вопрос подряд десяток раз — дайте ситуации пространство откликнуться.` },
  ];
  const intents = (item.intents || []).filter(Boolean);
  return { ...item, intro, sections, intents };
}

function toTs(article) {
  const intents = article.intents.map((s) => q(s)).join(", ");
  const links = article.links
    .map((l) => `      { href: ${q(l.href)}, title: ${q(l.title)} }`)
    .join(",\n");
  const sections = article.sections
    .map(
      (s) => `      {
        heading: ${q(s.heading)},
        body: ${q(s.body)},
      }`
    )
    .join(",\n");
  return `  {
    slug: ${q(article.slug)},
    title: ${q(article.title)},
    description: ${q(article.description)},
    intro: ${q(article.intro)},
    sections: [
${sections}
    ],
    intentSlugs: [${intents}],
    relatedHrefs: [
${links}
    ],
  }`;
}

const articles = ALL.map(buildArticle);
const unique = new Map();
for (const a of articles) {
  if (unique.has(a.slug)) throw new Error(`Duplicate slug: ${a.slug}`);
  unique.set(a.slug, a);
}

const out = `/** Auto-generated content plan (${articles.length} articles). Regenerate: node scripts/generate-seo-articles.mjs */
import type { SeoArticle } from "./articles-types";

export const SEO_ARTICLES_EXTRA: SeoArticle[] = [
${articles.map(toTs).join(",\n")}
];
`;

const target = join(__dir, "..", "src", "lib", "seo", "articles-extra.ts");
writeFileSync(target, out, "utf8");
const slugsPath = join(__dir, "seo-article-extra-slugs.json");
writeFileSync(slugsPath, JSON.stringify(articles.map((a) => a.slug), null, 2) + "\n", "utf8");
console.log(`Wrote ${articles.length} articles -> ${target}`);
console.log(`Wrote slugs -> ${slugsPath}`);
